_elementor_page_settings.custom_css:
/* Cabeçalho fixo em todas as páginas. Na home, nas páginas de roteiro e na Sobre (#7): transparente no topo, fundo branco ao rolar (CSS de rolagem, sem JS).
   Gravado no CSS personalizado do template Header #932. Navegador sem suporte a
   animation-timeline fica com o cabeçalho sempre branco. */
.elementor-location-header{position:sticky;top:0;z-index:999;background:#fff;box-shadow:0 2px 12px rgba(0,0,0,.08)}
.admin-bar .elementor-location-header{top:32px}
@media (max-width:782px){.admin-bar .elementor-location-header{top:46px}}
:is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header{position:fixed;left:0;right:0}
body.home h1.entry-title{display:none}
.elementor-location-header .elementor-element-20ccf12{margin-bottom:0}
@supports (animation-timeline: scroll()){
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header,
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-element-20ccf12,
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-nav-menu--main .elementor-item,
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-element-89569b3 .elementor-icon i,
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-element-89569b3 .elementor-icon svg{animation-timing-function:linear;animation-fill-mode:both;animation-timeline:scroll(root);animation-range:0 120px}
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header{animation-name:rt-hdr}
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-element-20ccf12{animation-name:rt-hdr-borda}
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-nav-menu--main .elementor-item{animation-name:rt-hdr-menu}
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-element-89569b3 .elementor-icon i,
  :is(body.home,body.single-roteiros,body.page-id-7) .elementor-location-header .elementor-element-89569b3 .elementor-icon svg{animation-name:rt-hdr-icone}
}
@keyframes rt-hdr{from{background:rgba(255,255,255,0);box-shadow:0 2px 12px rgba(0,0,0,0)}to{background:#fff;box-shadow:0 2px 12px rgba(0,0,0,.08)}}
@keyframes rt-hdr-borda{from{border-bottom-color:rgba(255,183,0,0)}to{border-bottom-color:#FFB700}}
@keyframes rt-hdr-menu{from{color:#fff;text-shadow:0 1px 4px rgba(0,0,0,.6)}to{color:#E98300;text-shadow:none}}
@keyframes rt-hdr-icone{from{color:#fff;fill:#fff;filter:drop-shadow(0 1px 3px rgba(0,0,0,.6))}to{color:#3C3D3D;fill:#3C3D3D;filter:none}}
